insert into public.settings (id, business_name, tagline, whatsapp, hours, instagram, facebook, site_url, show_prices, design) values
  (1, 'El Juanse Bazar', 'Bazar a medida', '5491126763257', 'Lun a vie 9 a 19 h · Sáb 9 a 14 h', '@eljuansebazar', 'El Juanse Bazar', '', false, '{"heroEyebrow": "Bazar a medida", "heroTitle": "Todo para tu cocina y tu casa, en un solo lugar", "heroText": "Vajilla, organización, deco y artículos de bazar para tu casa o tu empresa, con la opción de personalizarlos con tu logo. Mirá el catálogo y pedinos una cotización por WhatsApp.", "heroCta": "Ver catálogo", "heroProducts": ["V003", "O014", "D001"], "promoTitle": "Semana del bazar", "promoText": "Precios especiales en vajilla y organización hasta agotar stock.", "waTitle": "¿No encontrás lo que buscás?", "waText": "Tenemos más artículos de los que ves en la web. Escribinos con una foto o una idea y te decimos si lo conseguimos.", "customEyebrow": "Regalos empresariales", "customTitle": "Tu marca, en los productos que la gente usa todos los días", "customText": "Personalizamos tazas, vasos, tablas, frascos y más con el logo de tu empresa. Ideal para regalos de fin de año, eventos, kits de bienvenida y merchandising."}'::jsonb)
