insert into public.faqs (question, answer, position) values
  ('¿Hay un mínimo de compra?', 'Para compras de productos del catálogo no hay mínimo. Para productos personalizados con logo, el mínimo depende del artículo y la técnica: en general desde 12 unidades.', 0),
  ('¿Cuánto tarda la producción de un pedido personalizado?', 'Entre 7 y 15 días hábiles desde que aprobás el boceto y se confirma el pedido. En fechas de alta demanda, como fin de año, conviene consultar con más anticipación.', 1),
  ('¿Cuánto tarda la entrega?', 'Los productos con stock se despachan dentro de las 48 h hábiles de confirmado el pago. El tiempo de viaje depende de la zona y del transporte elegido.', 2),
  ('¿Hacen envíos a todo el país?', 'Sí, enviamos a todo el país por correo o transporte. En CABA y GBA también coordinamos envíos en moto. El costo se calcula según destino, peso y volumen.', 3),
  ('¿Qué formas de pago aceptan?', 'Transferencia bancaria y Mercado Pago. Para empresas emitimos factura A o B. Las compras no se pagan en la web: coordinamos todo por WhatsApp.', 4),
  ('¿Cómo hago un pedido?', 'Agregá los productos a tu lista de consulta y envianosla por WhatsApp. Te confirmamos stock, precio final y costo de envío, y te pasamos los datos de pago.', 5);
